import { z } from 'zod';
// Duplicated in packages/auth-edge/src/page-groups.ts, which validation cannot depend on. Keep the two schemas in sync.
const WILDCARD_GROUP = '*';
const groupNameSchema = z.string().min(1);
const groupRuleSchema = z
    .object({
    includes: z
        .array(groupNameSchema)
        .min(1, 'Omit includes to allow every group, or set groups to [] to deny everyone')
        .optional(),
    excludes: z
        .array(groupNameSchema)
        .optional()
        .refine((excludes) => !(excludes === null || excludes === void 0 ? void 0 : excludes.includes(WILDCARD_GROUP)), {
        message: 'The * wildcard is not allowed in excludes',
    }),
})
    .strict();
export const pageGroupsSchema = z
    .union([z.array(groupNameSchema), z.array(groupRuleSchema)])
    .describe('User groups that can see the page. Either a list of group names, or a list of { includes, excludes } rules. Readers in an excluded group never see the page.');
